<?php
require_once __DIR__ . '/../app/inventory-service.php';
$restaurantId = (int)$context['restaurant_id'];
$materials = inventory_stock_snapshot($db, $restaurantId);
$units = inventory_unit_list($db, $restaurantId);
$filterMaterial = max(0, (int)($_GET['material'] ?? 0));
$movementQuery = $db->prepare('SELECT x.id, x.movement_type, x.quantity_base, x.unit_cost, x.cost_amount, x.source_type, x.source_id, x.effective_at, x.notes, m.name AS material_name, u.symbol AS base_symbol, a.name AS actor_name, SUM(x.quantity_base) OVER (PARTITION BY x.material_id ORDER BY x.id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS balance_after FROM inventory_stock_movements x JOIN inventory_materials m ON m.id = x.material_id AND m.restaurant_id = x.restaurant_id JOIN inventory_units u ON u.id = m.base_unit_id AND u.restaurant_id = m.restaurant_id LEFT JOIN users a ON a.id = x.actor_user_id AND (a.restaurant_id = x.restaurant_id OR a.restaurant_id IS NULL) WHERE x.restaurant_id = ? AND (? = 0 OR x.material_id = ?) ORDER BY x.id DESC LIMIT 100');
$movementQuery->execute([$restaurantId, $filterMaterial, $filterMaterial]);
$movements = $movementQuery->fetchAll();
?>
<div class="page-heading"><div><p class="eyebrow">STOCK LEDGER</p><h2>Stock</h2><p>Current quantities and value are backed by the append-only movement ledger.</p></div></div>
<section class="panel-card form-panel"><div class="panel-title"><div><p class="eyebrow">INITIAL STOCK</p><h3>Enter opening stock</h3></div><span class="metric-icon">＋</span></div>
    <?php if (!$materials || !$units): ?><p class="empty-state">Add at least one material and unit before entering opening stock.</p><?php else: ?>
    <form method="post" action="<?= inv_e(inv_route('stock')) ?>" class="form-grid">
        <input type="hidden" name="action" value="opening-stock"><input type="hidden" name="return_page" value="stock"><input type="hidden" name="csrf" value="<?= inv_e($csrf) ?>"><input type="hidden" name="idempotency_key" value="<?= inv_e(bin2hex(random_bytes(32))) ?>">
        <label>Material<select name="material_id" required><option value="">Select material</option><?php foreach ($materials as $material): if (!(int)$material['is_active']) continue; ?><option value="<?= (int)$material['id'] ?>"><?= inv_e($material['name'] . ' (' . $material['base_unit_symbol'] . ' base)') ?></option><?php endforeach; ?></select></label>
        <label>Unit<select name="unit_id" required><option value="">Select unit</option><?php foreach ($units as $unit): ?><option value="<?= (int)$unit['id'] ?>"><?= inv_e($unit['name'] . ' (' . $unit['symbol'] . ') · ' . $unit['dimension']) ?></option><?php endforeach; ?></select></label>
        <label>Quantity<input name="quantity" type="number" min="0.000001" step="0.000001" required></label><label>Cost per selected unit (LKR)<input name="unit_cost" type="number" min="0" step="0.01" required></label>
        <label class="span-all">Reason / note<input name="notes" maxlength="1000" value="Opening stock"></label><button class="button button-primary" type="submit">Post Opening Stock</button>
    </form><?php endif; ?>
</section>
<section class="panel-card data-panel"><div class="panel-title panel-title-wrap"><div><p class="eyebrow">LIVE BALANCE</p><h3>Current stock</h3></div><label class="search-field">Search<input type="search" placeholder="Material or SKU" data-table-search="stock-table"></label></div>
<?php if (!$materials): ?><p class="empty-state">No materials yet.</p><?php else: ?><div class="table-scroll"><table class="data-table" id="stock-table"><thead><tr><th>Material</th><th>Current quantity</th><th>Avg. cost / base unit</th><th>Stock value</th><th>Reorder level</th><th>Status</th></tr></thead><tbody><?php foreach ($materials as $material): $qty=(float)$material['quantity_base']; $minimum=(float)$material['minimum_quantity']; $status=$qty<0?'Negative stock':($qty<=0?'Out of stock':($minimum>0&&$qty<=$minimum?'Low stock':'Normal')); ?><tr data-search-row="<?= inv_e(mb_strtolower($material['name'].' '.($material['sku']??''))) ?>"><td><strong><?= inv_e($material['name']) ?></strong><small class="table-subtext"><?= inv_e($material['sku'] ?: 'No SKU') ?></small></td><td><?= inv_e(inv_decimal($qty,4).' '.$material['base_unit_symbol']) ?></td><td><?= inv_e(inv_money($material['average_cost'])) ?></td><td><?= inv_e(inv_money($material['inventory_value'])) ?></td><td><?= inv_e(inv_decimal($minimum,4).' '.$material['base_unit_symbol']) ?></td><td><span class="status-pill<?= $status==='Normal'?'':' status-off' ?>"><?= inv_e($status) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section>
<section class="panel-card data-panel"><div class="panel-title panel-title-wrap"><div><p class="eyebrow">AUDIT TRAIL</p><h3>Stock movement history</h3></div><form method="get" action="<?= inv_e(inv_base_path()) ?>/index.php" class="search-field"><input type="hidden" name="page" value="stock"><label for="movement-material-filter">Material</label><select id="movement-material-filter" name="material" data-auto-submit><option value="0">All materials</option><?php foreach ($materials as $material): ?><option value="<?= (int)$material['id'] ?>"<?= $filterMaterial===(int)$material['id']?' selected':'' ?>><?= inv_e($material['name']) ?></option><?php endforeach; ?></select></form></div>
<?php if (!$movements): ?><p class="empty-state">No stock movements match this selection.</p><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Date/time (UTC)</th><th>Material</th><th>Type</th><th>Quantity</th><th>Ledger balance</th><th>Cost</th><th>Reference</th><th>Actor</th></tr></thead><tbody><?php foreach ($movements as $movement): ?><tr><td><?= inv_e($movement['effective_at']) ?></td><td><?= inv_e($movement['material_name']) ?></td><td><span class="status-pill"><?= inv_e($movement['movement_type']) ?></span></td><td><?= inv_e(inv_decimal($movement['quantity_base'],4).' '.$movement['base_symbol']) ?></td><td><?= inv_e(inv_decimal($movement['balance_after'],4).' '.$movement['base_symbol']) ?></td><td><?= inv_e(inv_money($movement['cost_amount'])) ?></td><td><?= inv_e($movement['source_type'].' '.($movement['source_id'] ?? '')) ?></td><td><?= inv_e($movement['actor_name'] ?? 'System / unavailable') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section>

